use super::*;
#[test]
fn original_external_source_plan_never_fabricates_persistent_members(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["external"].as_array().unwrap(){let bytes=row["source"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>();let result=import_document(row["format"].as_str().unwrap(),&bytes,row["name"].as_str().unwrap(),&mut |_|true);assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());if let Ok(result)=result{let LayoutImportSourcePlan::External{format,source,name}=result.value else{panic!("external source was misrepresented as a persistent document")};assert_eq!(source,bytes);assert_eq!(name,row["name"].as_str().unwrap());assert_eq!(match format{LayoutExternalDrawingFormat::Svg=>"svg",LayoutExternalDrawingFormat::Dxf=>"dxf",LayoutExternalDrawingFormat::Dwg=>"dwg"},row["format"].as_str().unwrap());assert_ne!(source.as_ptr(),bytes.as_ptr());}assert!(import_document(row["format"].as_str().unwrap(),&bytes,"Cancelled",&mut |_|false).is_err());}}

#[test]
fn real_external_helper_observes_each_bounded_copy_checkpoint(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["chunks"].as_array().unwrap(){let length=row["length"].as_u64().unwrap()as usize;let input=(0..length).map(|at|(at%256)as u8).collect::<Vec<_>>();let expected=row["checkpoints"].as_array().unwrap().iter().map(|at|at.as_u64().unwrap()as usize).collect::<Vec<_>>();let mut seen=Vec::new();let plan=crate::layout_import_sources_from_format("svg",&input,"Opaque byte chunks",&mut |progress|{assert_eq!(progress.total,length);seen.push(progress.completed);true}).unwrap();assert_eq!(seen,expected);let LayoutImportSourcePlan::External{source,..}=plan else{panic!("opaque source became a published document")};assert_eq!(source,input);for stop in 0..expected.len(){let mut at=0;let result=crate::layout_import_sources_from_format("svg",&input,"Cancelled chunks",&mut |_|{let allowed=at<stop;at+=1;allowed});assert!(matches!(result,Err(error)if error=="layout.interchange.cancelled"));assert_eq!(at,stop+1);}}}
